import AppKit
import Observation
import QuickLookThumbnailing
import SwiftUI

/// Finder-style previews of local files, generated by the system off the main actor. The
/// most recently asked for are kept, so scrolling through a folder of tens of thousands of
/// files does not hold a picture of each. A file that is gone or has no preview gets the
/// drawn stand-in.
@MainActor
@Observable
final class ThumbnailCache {
    /// How many previews are remembered; the older half is dropped when it is passed.
    static let limit = 800

    private var images: [String: NSImage] = [:]
    @ObservationIgnored private var requested: Set<String> = []
    /// Keys in the order they were first asked for.
    @ObservationIgnored private var order: [String] = []
    /// Produces the preview; replaced in tests and offscreen renders.
    @ObservationIgnored private let generate: @Sendable (URL, CGFloat, CGFloat) async -> CGImage?

    init(generate: @escaping @Sendable (URL, CGFloat, CGFloat) async -> CGImage? = ThumbnailCache.quickLook) {
        self.generate = generate
    }

    /// The cached preview, if it has been generated. Starts generating it otherwise.
    func image(for path: String, side: CGFloat, scale: CGFloat) -> NSImage? {
        let key = "\(Int(side))|\(path)"
        if let image = images[key] { return image }
        if requested.insert(key).inserted {
            order.append(key)
            if order.count > Self.limit { forgetOldest(Self.limit / 2) }
            Task {
                guard let cgImage = await generate(URL(fileURLWithPath: path), side, scale) else { return }
                // Forgotten while it was being generated: it is asked for again if still shown.
                guard requested.contains(key) else { return }
                images[key] = NSImage(
                    cgImage: cgImage,
                    size: CGSize(width: CGFloat(cgImage.width) / scale, height: CGFloat(cgImage.height) / scale))
            }
        }
        return nil
    }

    private func forgetOldest(_ count: Int) {
        let oldest = order.prefix(count)
        requested.subtract(oldest)
        let held = oldest.filter { images[$0] != nil }
        if !held.isEmpty {
            for key in held { images[key] = nil }
        }
        order.removeFirst(min(count, order.count))
    }

    @Sendable
    nonisolated static func quickLook(_ url: URL, side: CGFloat, scale: CGFloat) async -> CGImage? {
        let request = QLThumbnailGenerator.Request(
            fileAt: url, size: CGSize(width: side, height: side), scale: scale,
            representationTypes: [.thumbnail, .icon])
        return try? await QLThumbnailGenerator.shared.generateBestRepresentation(for: request).cgImage
    }
}

/// The preview of an uploaded file, fitted inside a square of `side` points.
struct ThumbnailView: View {
    let path: String
    let fileName: String
    var side: CGFloat = 30
    @Environment(ThumbnailCache.self) private var cache
    @Environment(\.displayScale) private var displayScale

    var body: some View {
        if let image = cache.image(for: path, side: side, scale: displayScale) {
            Image(nsImage: image)
                .resizable()
                .interpolation(.high)
                .aspectRatio(contentMode: .fit)
                .frame(maxWidth: side, maxHeight: side)
                .shadow(color: .black.opacity(0.25), radius: 1.5, y: 1)
        } else {
            GenericFileIcon(fileName: fileName, height: side * 28 / 30)
        }
    }
}

/// What stands for a whole upload: the file's preview, a folder, or a pile of the first
/// items when several were sent together.
struct UploadThumbnail: View {
    let record: UploadRecord
    var side: CGFloat = 30

    var body: some View {
        switch record.kind {
        case .singleFile:
            ThumbnailView(path: record.localPath, fileName: record.fileName, side: side)
        case .folder:
            FolderIcon(width: side)
        case .multiple:
            ThumbnailStack(paths: Array(record.handedPaths.prefix(3)), side: side)
        }
    }
}

/// The mockups' folder (`th-folder`): a blue body with a tab on its top left corner. Drawn
/// for 30 points of width and scaled from there, which gives the detail's 50 point folder.
struct FolderIcon: View {
    var width: CGFloat = 30

    var body: some View {
        let scale = width / 30
        let bodyHeight = (21 * scale).rounded()
        let bodyTop = (5 * scale).rounded()
        let tabRise = (4 * scale).rounded()
        ZStack(alignment: .topLeading) {
            RoundedRectangle(cornerRadius: 3 * scale)
                .fill(
                    LinearGradient(
                        colors: [Theme.dynamic(0x72C4F7, 0x72C4F7), Theme.dynamic(0x3B97E3, 0x3B97E3)],
                        startPoint: .top, endPoint: .bottom)
                )
                .frame(width: width, height: bodyHeight)
                .offset(y: bodyTop)
            UnevenRoundedRectangle(
                topLeadingRadius: (2 * scale).rounded(), bottomLeadingRadius: 0, bottomTrailingRadius: 0,
                topTrailingRadius: 3 * scale
            )
            .fill(Theme.dynamic(0x58AEEC, 0x58AEEC))
            .frame(width: (13 * scale).rounded(), height: (7 * scale).rounded())
            .offset(y: bodyTop - tabRise)
        }
        .frame(width: width, height: bodyTop + bodyHeight, alignment: .topLeading)
    }
}

/// The mockups' pile (`th-stack`) for several items sent together: the first item on top,
/// the next two leaning out behind it.
struct ThumbnailStack: View {
    let paths: [String]
    var side: CGFloat = 30

    var body: some View {
        let scale = side / 30
        ZStack {
            if paths.count > 1 {
                thumbnail(paths[1]).rotationEffect(.degrees(-11)).offset(x: -7 * scale, y: -1 * scale)
            }
            if paths.count > 2 {
                thumbnail(paths[2]).rotationEffect(.degrees(9)).offset(x: 7 * scale, y: 1 * scale)
            }
            if let first = paths.first {
                thumbnail(first)
            }
        }
    }

    private func thumbnail(_ path: String) -> some View {
        ThumbnailView(path: path, fileName: (path as NSString).lastPathComponent, side: side)
    }
}

/// The mockups' stand-in for a file with no preview: a small page with its extension.
struct GenericFileIcon: View {
    let fileName: String
    var height: CGFloat = 28

    var body: some View {
        let label = String((fileName as NSString).pathExtension.uppercased().prefix(4))
        RoundedRectangle(cornerRadius: 2)
            .fill(Theme.dynamic(0xF4F5F8, 0xF4F5F8))
            .overlay(alignment: .bottom) {
                Text(label)
                    .font(.system(size: max(height * 6 / 28, 5), weight: .bold))
                    .foregroundStyle(Theme.dynamic(0x7A8094, 0x7A8094))
                    .padding(.bottom, height * 3 / 28)
            }
            .overlay { RoundedRectangle(cornerRadius: 2).strokeBorder(.black.opacity(0.2), lineWidth: 1) }
            .frame(width: height * 22 / 28, height: height)
            .shadow(color: .black.opacity(0.25), radius: 1.5, y: 1)
    }
}
